212	async function eventually(predicate: () => Promise<boolean>, message: string, timeoutMs = 10_000): Promise<void> {
213	  const deadline = Date.now() + timeoutMs;
214	  while (Date.now() < deadline) {
215	    if (await predicate()) return;
216	    await new Promise(resolve => setTimeout(resolve, 10));
217	  }
218	  throw new Error(message);
219	}
