369	  root: string,
370	  runId: string,
371	  receiptId: string,
372	  readyPath: string,
373	  goPath: string,
374	  resultPath: string,
375	  afterReviewPassReadPath?: string,
376	  persistBarrierPath?: string,
377	): Promise<void> {
378	  process.chdir(root);
379	  resetConfigCache();
380	  writeFileSync(readyPath, 'ready');
381	  await eventually(async () => {
382	    try { readFileSync(goPath); return true; } catch { return false; }
383	  }, 'concurrent import barrier was never released');
384	  const store = new StoryStore(root);
385	  if (afterReviewPassReadPath && persistBarrierPath) {
386	    const readReviewPasses = store.readReviewPasses.bind(store);
387	    const readFindings = store.readFindings.bind(store);
388	    let reviewPassReads = 0;
389	    let findingReads = 0;
390	    store.readReviewPasses = ((storyId: string) => {
391	      const data = readReviewPasses(storyId);
392	      reviewPassReads += 1;
393	      if (reviewPassReads === 2) {
394	        writeFileSync(afterReviewPassReadPath, 'read');
395	        while (!existsSync(persistBarrierPath)) {
396	          Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 10);
397	        }
398	      }
399	      return data;
400	    }) as typeof store.readReviewPasses;
401	    store.readFindings = ((storyId: string) => {
402	      const data = readFindings(storyId);
403	      findingReads += 1;
404	      if (findingReads === 2) {
405	        writeFileSync(afterReviewPassReadPath, 'read');
406	        while (!existsSync(persistBarrierPath)) {
407	          Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 10);
408	        }
409	      }
410	      return data;
411	    }) as typeof store.readFindings;
412	  }
413	  const handlers = createManagedReviewEvidenceHandlers({ store, root, scanRoot: join(root, 'packages/main') });
414	  let resolvedReceiptId = receiptId;
415	  if (receiptId === 'AUTO') {
416	    await eventually(async () => {
417	      try {
418	        resolvedReceiptId = managedHostRunReceipt(root, runId).receiptId;
419	        return true;
420	      } catch { return false; }
421	    }, 'import worker did not observe the exclusive terminal receipt');
422	  }
423	  const result = handlers.managed_review_evidence_import({ runId, receiptId: resolvedReceiptId });
424	  writeFileSync(resultPath, `${result}\n`);
