14	    const relativePath = relativeDir ? `${relativeDir}/${entry.name}` : entry.name;
15	    if (entry.isDirectory()) {
16	      if (!['tasks', 'tests', 'generated'].includes(entry.name)) {
17	        rows.push(...productionSources(sourceRoot, relativePath));
18	      }
19	      continue;
20	    }
21	    if (entry.isFile() && relativePath.endsWith('.ts')) {
22	      rows.push({ path: relativePath, source: readFileSync(join(sourceRoot, relativePath), 'utf8') });
23	    }
24	  }
25	  return rows;
26	}
